import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Identify highly significant features (p < 0.01)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'expression' or feats.types[i] == 'copy_number':
            t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])[0]
            p_val = 1 - stats.t.cdf(abs(t_stat), len(feats.y)-2)
            if p_val < 0.01:
                sig_features.append((fid, abs(t_stat)))

    # Sort by significance
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # If no significant features, return empty design
    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Remove near-duplicates based on correlation
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i < j:
                corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
                if abs(corr) >= 0.6:
                    correlations[(fid1, fid2)] = corr

    # Group correlated features and select most significant from each group
    selected_features = set()
    visited = set()

    # Process correlations to form groups
    for fid1, fid2 in correlations:
        if fid1 not in visited and fid2 not in visited:
            # Create a group with these two features
            group = {fid1, fid2}
            visited.add(fid1)
            visited.add(fid2)

            # Add other correlated features to this group
            for fid3, fid4 in correlations:
                if fid3 in group or fid4 in group:
                    group.add(fid3)
                    group.add(fid4)
                    visited.add(fid3)
                    visited.add(fid4)

            # From this group, select the most significant feature
            max_t = -1
            most_sig_fid = None
            for fid in group:
                if fid in feats.ids:  # Ensure fid exists in our dataset
                    col_idx = feats.column(fid)
                    t_stat = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx])[0]
                    if abs(t_stat) > max_t:
                        max_t = abs(t_stat)
                        most_sig_fid = fid
            if most_sig_fid:
                selected_features.add(most_sig_fid)

    # Add remaining significant features not in any group
    for fid, _ in sig_features:
        if fid not in selected_features and fid not in visited:
            selected_features.add(fid)

    # Select top features by significance (max MAX_DRIVERS)
    top_features = [fid for fid, _ in sorted(sig_features, key=lambda x: x[1], reverse=True) 
                   if fid in selected_features][:MAX_DRIVERS]

    # Build loadings dictionary
    loadings = {}
    for fid in top_features:
        col_idx = feats.column(fid)
        # Weight by t-statistic
        t_stat = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx])[0]
        loadings[fid] = abs(t_stat)

    # Return design
    return Design(
        drivers=tuple(top_features),
        columns=tuple(top_features),
        products=(),
        loadings=loadings
    )

